export function validateRustOwnedCredentialPolicy(token: string): void {
  if ((RUST_OWNED_CREDENTIAL_POLICY as string) === "bearer-no-crlf" && (!token.trim() || /[\r\n]/.test(token))) throw new TypeError("invalid bearer credential");
}

export function validateRustOwnedCredential(method: RustOwnedMethodMetadata, token: string): void {
  if ((method.credentialPolicy as string) === (RUST_OWNED_CREDENTIAL_POLICY as string)) validateRustOwnedCredentialPolicy(token);
}

export type WorkersMethod = keyof typeof WORKERS_METHODS;

export interface RustOwnedInvoker {
  invoke<TRequest, TResponse>(method: RustOwnedMethodMetadata, request: TRequest): Promise<TResponse>;
}

export function createWorkersClient(invoker: RustOwnedInvoker) {
  return {
    publishVersion(request: PublishVersionRequest): Promise<PublishVersionResponse> {
      return invoker.invoke<PublishVersionRequest, PublishVersionResponse>(WORKERS_METHODS.publishVersion, request);
    },
    selectDeployment(request: SelectDeploymentRequest): Promise<SelectDeploymentResponse> {
      return invoker.invoke<SelectDeploymentRequest, SelectDeploymentResponse>(WORKERS_METHODS.selectDeployment, request);
    },
    submitJob(request: SubmitJobRequest): Promise<SubmitJobResponse> {
      return invoker.invoke<SubmitJobRequest, SubmitJobResponse>(WORKERS_METHODS.submitJob, request);
    },
    inspectJob(request: InspectJobRequest): Promise<InspectJobResponse> {
      return invoker.invoke<InspectJobRequest, InspectJobResponse>(WORKERS_METHODS.inspectJob, request);
    },
    cancelJob(request: CancelJobRequest): Promise<CancelJobResponse> {
      return invoker.invoke<CancelJobRequest, CancelJobResponse>(WORKERS_METHODS.cancelJob, request);
    },
    invokeVersion(request: InvokeVersionRequest): Promise<InvokeResponse> {
      return invoker.invoke<InvokeVersionRequest, InvokeResponse>(WORKERS_METHODS.invokeVersion, request);
    },
    invokeDeployment(request: InvokeDeploymentRequest): Promise<InvokeResponse> {
      return invoker.invoke<InvokeDeploymentRequest, InvokeResponse>(WORKERS_METHODS.invokeDeployment, request);
    },
  } as const;
}
